package sroar

import (
	"math/rand"
	"sort"
	"testing"
)

// Benchmarks comparing N-way union strategies across different source shapes:
//
//   - tiny sources (cardinality 1) — many singleton bitmaps, the shape that
//     makes pairwise merge slow
//   - mixed (tiny sources plus a few large ones)
//   - few large sources
//
// Strategies:
//
//   - IterOr:     acc.Or(src) one source at a time
//   - FastOr:     sroar's variadic two-pass union
//   - SortedList: extract all elements, sort, dedup, FromSortedList
//   - Accumulator: dense staging
func BenchmarkOr(b *testing.B) {
	makeTiny := func(rng *rand.Rand, n int, universe uint64) []*Bitmap {
		sources := make([]*Bitmap, n)
		for i := range sources {
			bm := NewBitmap()
			bm.Set(rng.Uint64() % universe)
			sources[i] = bm
		}
		return sources
	}
	makeLarge := func(seed int64, n, card int, universe uint64) []*Bitmap {
		sources := make([]*Bitmap, n)
		for i := range sources {
			sources[i] = randomBitmap(seed+int64(i), card, universe)
		}
		return sources
	}
	// Clustered: singletons of consecutive values, perBlock per 64K range,
	// sitting mid-range — sequential doc-ID runs, the shape whose touched
	// window per staging block is far narrower than the block.
	makeClusteredTiny := func(n, perBlock int) []*Bitmap {
		sources := make([]*Bitmap, n)
		for i := range sources {
			block, off := uint64(i/perBlock), uint64(i%perBlock)
			sources[i] = NewBitmap()
			sources[i].Set(block<<16 + 30_000 + off)
		}
		return sources
	}

	fixtures := []struct {
		name    string
		sources []*Bitmap
	}{
		{"tiny_1k_u300k", makeTiny(rand.New(rand.NewSource(1)), 1_000, 300_000)},
		{"tiny_10k_u300k", makeTiny(rand.New(rand.NewSource(2)), 10_000, 300_000)},
		{"tiny_100k_u300k", makeTiny(rand.New(rand.NewSource(3)), 100_000, 300_000)},
		{"tiny_100k_u10m", makeTiny(rand.New(rand.NewSource(4)), 100_000, 10_000_000)},
		{"tiny_100k_u100m", makeTiny(rand.New(rand.NewSource(8)), 100_000, 100_000_000)},
		{"tiny_100k_u300m", makeTiny(rand.New(rand.NewSource(9)), 100_000, 300_000_000)},
		{"tiny_100k_u1b", makeTiny(rand.New(rand.NewSource(10)), 100_000, 1_000_000_000)},
		{"tiny_100k_clustered8", makeClusteredTiny(100_000, 8)},
		{"mixed_10k_tiny_5_large_u10m", append(
			makeTiny(rand.New(rand.NewSource(5)), 10_000, 10_000_000),
			makeLarge(6, 5, 200_000, 10_000_000)...)},
		{"large_8x1m_u10m", makeLarge(7, 8, 1_000_000, 10_000_000)},
	}

	strategies := []struct {
		name  string
		union func(sources []*Bitmap) *Bitmap
	}{
		{"IterOr", func(sources []*Bitmap) *Bitmap {
			acc := NewBitmap()
			for _, s := range sources {
				acc.Or(s)
			}
			return acc
		}},
		{"FastOr", func(sources []*Bitmap) *Bitmap {
			return FastOr(sources...)
		}},
		{"SortedList", func(sources []*Bitmap) *Bitmap {
			var vals []uint64
			for _, s := range sources {
				vals = append(vals, s.ToArray()...)
			}
			sort.Slice(vals, func(i, j int) bool { return vals[i] < vals[j] })
			// Dedup in place; FromSortedList requires strictly deduped input.
			n := 0
			for i, v := range vals {
				if i == 0 || v != vals[n-1] {
					vals[n] = v
					n++
				}
			}
			return FromSortedList(vals[:n])
		}},
		{"Accumulator", func(sources []*Bitmap) *Bitmap {
			acc := NewAccumulator()
			for _, s := range sources {
				acc.Or(s)
			}
			return acc.Bitmap()
		}},
	}

	for _, fx := range fixtures {
		// Sanity: all strategies must agree before their numbers mean anything.
		want := strategies[0].union(fx.sources).GetCardinality()
		for _, st := range strategies[1:] {
			if got := st.union(fx.sources).GetCardinality(); got != want {
				b.Fatalf("%s/%s: cardinality %d, want %d", fx.name, st.name, got, want)
			}
		}
		for _, st := range strategies {
			b.Run(fx.name+"/"+st.name, func(b *testing.B) {
				b.ReportAllocs()
				for i := 0; i < b.N; i++ {
					_ = st.union(fx.sources)
				}
			})
		}
	}
}

// BenchmarkAccumulatorReuse measures a warm, retention-configured accumulator
// reused across unions (the pooled shape): Reset then rebuild, so staging
// blocks are claimed from the free list rather than allocated fresh. The dense
// and sparse variants exercise the two claim paths — a bitmap-container source
// adopts a fresh block by copy (the spare is claimed dirty, no clear), while an
// array/singleton source ORs in (the spare is zeroed on claim).
func BenchmarkAccumulatorReuse(b *testing.B) {
	makeDense := func(nRanges, perRange int) []*Bitmap {
		sources := make([]*Bitmap, nRanges)
		for k := 0; k < nRanges; k++ {
			vals := make([]uint64, perRange)
			base := uint64(k) << 16
			for i := range vals {
				vals[i] = base + uint64(i)
			}
			sources[k] = bitmapOf(vals...)
		}
		return sources
	}
	makeSparse := func(nRanges int) []*Bitmap {
		sources := make([]*Bitmap, nRanges)
		for k := 0; k < nRanges; k++ {
			sources[k] = bitmapOf(uint64(k)<<16 | 7)
		}
		return sources
	}

	fixtures := []struct {
		name    string
		sources []*Bitmap
	}{
		{"dense_64x3000", makeDense(64, 3000)},   // bitmap-container copy path
		{"sparse_64x1", makeSparse(64)},          // array OR-in / clear path
		{"dense_512x3000", makeDense(512, 3000)}, // wider spread, more spares
	}

	for _, fx := range fixtures {
		b.Run(fx.name, func(b *testing.B) {
			acc := NewAccumulator().WithRetainedBlocks(len(fx.sources))
			for _, s := range fx.sources { // warm the free list
				acc.Or(s)
			}
			acc.Reset()
			b.ReportAllocs()
			b.ResetTimer()
			for i := 0; i < b.N; i++ {
				acc.Reset()
				for _, s := range fx.sources {
					acc.Or(s)
				}
			}
		})
	}
}

package sroar

import (
	"testing"

	"github.com/stretchr/testify/require"
)

func makeNodeForSearch(numKeys int) node {
	bm := NewBitmap()
	for i := 0; i < numKeys; i++ {
		bm.Set(uint64(i+1) << 16)
	}
	return bm.keys
}

func TestSearchFrom(t *testing.T) {
	t.Run("gap of 1 — returns from+1 immediately", func(t *testing.T) {
		n := makeNodeForSearch(10)
		result := n.searchFrom(0, n.key(1))
		require.Equal(t, 1, result)
	})

	t.Run("exact match within range", func(t *testing.T) {
		n := makeNodeForSearch(100)
		for _, from := range []int{0, 10, 50} {
			for target := from + 1; target < n.numKeys(); target++ {
				k := n.key(target)
				got := n.searchFrom(from, k)
				require.Equal(t, target, got, "from=%d target=%d k=%d", from, target, k)
			}
		}
	})

	t.Run("between two keys returns first key >= k", func(t *testing.T) {
		n := makeNodeForSearch(50)
		between := n.key(5) + 1
		got := n.searchFrom(4, between)
		require.Equal(t, 6, got)
	})

	t.Run("k beyond all keys returns numKeys", func(t *testing.T) {
		n := makeNodeForSearch(20)
		beyond := n.key(n.numKeys()-1) + 1
		got := n.searchFrom(0, beyond)
		require.Equal(t, n.numKeys(), got)
	})

	t.Run("from at last position with k beyond returns numKeys", func(t *testing.T) {
		n := makeNodeForSearch(10)
		last := n.numKeys() - 1
		beyond := n.key(last) + 1
		got := n.searchFrom(last, beyond)
		require.Equal(t, n.numKeys(), got)
	})

	t.Run("from+1 >= numKeys returns numKeys", func(t *testing.T) {
		n := makeNodeForSearch(5)
		last := n.numKeys() - 1
		got := n.searchFrom(last, n.key(last)+1)
		require.Equal(t, n.numKeys(), got)
	})

	t.Run("large gap — exponential search path exercised", func(t *testing.T) {
		n := makeNodeForSearch(1000)
		target := n.numKeys() - 1
		k := n.key(target)
		got := n.searchFrom(0, k)
		require.Equal(t, target, got)
	})

	t.Run("large gap — between two distant keys", func(t *testing.T) {
		n := makeNodeForSearch(1000)
		between := n.key(900) + 1
		got := n.searchFrom(0, between)
		require.Equal(t, 901, got)
	})

	t.Run("agrees with search across all positions and targets", func(t *testing.T) {
		n := makeNodeForSearch(200)
		for from := 0; from < n.numKeys()-1; from++ {
			for _, offset := range []int{1, 2, 8, 16, 64, 128} {
				target := from + offset
				if target >= n.numKeys() {
					break
				}
				k := n.key(target)
				got := n.searchFrom(from, k)
				expected := n.search(k)
				require.Equal(t, expected, got, "from=%d offset=%d k=%d", from, offset, k)
			}
			if from+2 < n.numKeys() {
				between := n.key(from+1) + 1
				if between < n.key(from+2) {
					got := n.searchFrom(from, between)
					expected := n.search(between)
					require.Equal(t, expected, got, "from=%d between=%d", from, between)
				}
			}
		}
	})
}

