package sroar

import (
	"math/rand"
	"sort"
	"testing"

	"github.com/stretchr/testify/require"
)

func TestIteratorBasic(t *testing.T) {
	n := uint64(1e5)
	bm := NewBitmap()
	for i := uint64(1); i <= n; i++ {
		bm.Set(uint64(i))
	}

	it := bm.NewIterator()
	for i := uint64(1); i <= n; i++ {
		v := it.Next()
		require.Equal(t, i, v)
	}
	v := it.Next()
	require.Equal(t, uint64(0), v)
}

func TestIteratorRanges(t *testing.T) {
	n := uint64(1e5)
	bm := NewBitmap()
	for i := uint64(1); i <= n; i++ {
		bm.Set(uint64(i))
	}

	iters := bm.NewRangeIterators(8)
	cnt := uint64(1)
	for idx := 0; idx < 8; idx++ {
		it := iters[idx]
		for v := it.Next(); v > 0; v = it.Next() {
			require.Equal(t, cnt, v)
			cnt++
		}
	}
}

func TestIteratorRandom(t *testing.T) {
	n := uint64(1e6)
	bm := NewBitmap()
	mp := make(map[uint64]struct{})
	var arr []uint64
	for i := uint64(1); i <= n; i++ {
		v := uint64(rand.Intn(int(n) * 5))
		if v == 0 {
			continue
		}
		if _, ok := mp[v]; ok {
			continue
		}
		mp[v] = struct{}{}
		arr = append(arr, v)
		bm.Set(uint64(v))
	}

	sort.Slice(arr, func(i, j int) bool {
		return arr[i] < arr[j]
	})

	it := bm.NewIterator()
	v := it.Next()
	for i := uint64(0); i < uint64(len(arr)); i++ {
		require.Equal(t, arr[i], v)
		v = it.Next()
	}
}

func TestIteratorWithRemoveKeys(t *testing.T) {
	b := NewBitmap()
	N := uint64(1e6)
	for i := uint64(0); i < N; i++ {
		b.Set(i)
	}

	b.RemoveRange(0, N)
	it := b.NewIterator()

	cnt := 0
	for it.Next() > 0 {
		cnt++
	}
	require.Equal(t, 0, cnt)
}

func TestManyIterator(t *testing.T) {
	b := NewBitmap()
	for i := 0; i < int(1e6); i++ {
		b.Set(uint64(i))
	}

	mi := b.ManyIterator()
	buf := make([]uint64, 1000)

	i := 0
	for {
		got := mi.NextMany(buf)
		if got == 0 {
			break
		}
		require.Equal(t, 1000, got)
		require.Equal(t, uint64(i*1000), buf[0])
		i++
	}
}

func BenchmarkIterator(b *testing.B) {
	bm := NewBitmap()
	for i := 0; i < int(1e5); i++ {
		bm.Set(uint64(i))
	}

	b.ResetTimer()
	for i := 0; i < b.N; i++ {
		it := bm.NewIterator()
		for it.Next() > 0 {
		}
	}
}

package sroar

import (
	"math/rand"
	"testing"

	"github.com/stretchr/testify/require"
)

func randomBitmap(seed int64, n int, universe uint64) *Bitmap {
	rng := rand.New(rand.NewSource(seed))
	bm := NewBitmap()
	for i := 0; i < n; i++ {
		bm.Set(rng.Uint64() % universe)
	}
	return bm
}

func TestInitFromBufferUnlimited(t *testing.T) {
	src := randomBitmap(1, 10_000, 1_000_000)
	serialized := src.ToBufferWithCopy()

	t.Run("equivalent to FromBufferUnlimited", func(t *testing.T) {
		buf := make([]byte, len(serialized), len(serialized)+1024)
		copy(buf, serialized)

		var dst Bitmap
		InitFromBufferUnlimited(&dst, buf)
		require.Equal(t, FromBufferUnlimited(buf).ToArray(), dst.ToArray())
	})

	t.Run("reusing one struct across buffers", func(t *testing.T) {
		a := randomBitmap(2, 100, 10_000)
		b := randomBitmap(3, 200, 10_000)

		var dst Bitmap
		InitFromBufferUnlimited(&dst, a.ToBufferWithCopy())
		require.Equal(t, a.ToArray(), dst.ToArray())

		InitFromBufferUnlimited(&dst, b.ToBufferWithCopy())
		require.Equal(t, b.ToArray(), dst.ToArray())
	})

	t.Run("mutable within buffer capacity", func(t *testing.T) {
		buf := make([]byte, len(serialized), len(serialized)*2)
		copy(buf, serialized)

		var dst Bitmap
		InitFromBufferUnlimited(&dst, buf)
		require.True(t, dst.Set(999_999_999))
		require.True(t, dst.Contains(999_999_999))
	})

	t.Run("reinit drops the previous buffer", func(t *testing.T) {
		bufA := randomBitmap(7, 100, 10_000).ToBufferWithCopy()
		bufB := randomBitmap(8, 100, 10_000).ToBufferWithCopy()

		var dst Bitmap
		InitFromBufferUnlimited(&dst, bufA)
		require.Same(t, &bufA[0], &dst._ptr[0])

		InitFromBufferUnlimited(&dst, bufB)
		require.Same(t, &bufB[0], &dst._ptr[0])
	})

	t.Run("tiny buffer falls back to empty bitmap", func(t *testing.T) {
		var dst Bitmap
		InitFromBufferUnlimited(&dst, make([]byte, 0))
		require.True(t, dst.IsEmpty())
		require.True(t, dst.Set(42), "fallback bitmap must be mutable")
	})

	t.Run("tiny buffer fallback allocates only the backing slice", func(t *testing.T) {
		var dst Bitmap
		allocs := testing.AllocsPerRun(100, func() {
			InitFromBufferUnlimited(&dst, make([]byte, 0))
		})
		require.Equal(t, 1.0, allocs)
	})
}

func TestInitCloneToBuf(t *testing.T) {
	src := randomBitmap(4, 10_000, 1_000_000)

	t.Run("equivalent to CloneToBuf", func(t *testing.T) {
		buf := make([]byte, 0, src.LenInBytes()+1024)

		var dst Bitmap
		src.InitCloneToBuf(&dst, buf)
		require.Equal(t, src.ToArray(), dst.ToArray())
		require.Equal(t, src.CloneToBuf(make([]byte, 0, src.LenInBytes())).ToArray(), dst.ToArray())
	})

	t.Run("clone is independent of src", func(t *testing.T) {
		var dst Bitmap
		src.InitCloneToBuf(&dst, make([]byte, 0, src.LenInBytes()+1024))
		dst.Set(999_999_998)
		require.True(t, dst.Contains(999_999_998))
		require.False(t, src.Contains(999_999_998))
	})

	t.Run("reusing one struct across clones", func(t *testing.T) {
		a := randomBitmap(5, 100, 10_000)
		b := randomBitmap(6, 200, 10_000)
		buf := make([]byte, 0, max(a.LenInBytes(), b.LenInBytes()))

		var dst Bitmap
		a.InitCloneToBuf(&dst, buf)
		require.Equal(t, a.ToArray(), dst.ToArray())

		b.InitCloneToBuf(&dst, buf)
		require.Equal(t, b.ToArray(), dst.ToArray())
	})

	t.Run("reinit drops the previous buffer", func(t *testing.T) {
		a := randomBitmap(9, 100, 10_000)
		bufA := make([]byte, 0, a.LenInBytes())
		bufB := make([]byte, 0, a.LenInBytes())

		var dst Bitmap
		a.InitCloneToBuf(&dst, bufA)
		require.Same(t, &bufA[:1][0], &dst._ptr[0])

		a.InitCloneToBuf(&dst, bufB)
		require.Same(t, &bufB[:1][0], &dst._ptr[0])
	})

	t.Run("nil src initializes empty bitmap over buf", func(t *testing.T) {
		var nilSrc *Bitmap
		var dst Bitmap
		nilSrc.InitCloneToBuf(&dst, make([]byte, 0, 4096))
		require.True(t, dst.IsEmpty())
		require.True(t, dst.Set(7))
		require.True(t, dst.Contains(7))
	})

	t.Run("zero-value src initializes empty bitmap over buf", func(t *testing.T) {
		var src, dst Bitmap
		src.InitCloneToBuf(&dst, make([]byte, 0, 4096))
		require.True(t, dst.IsEmpty())
		require.True(t, dst.Set(7))
		require.True(t, dst.Contains(7))
	})

	t.Run("nil src with tiny buffer allocates only the backing slice", func(t *testing.T) {
		var nilSrc *Bitmap
		var dst Bitmap
		allocs := testing.AllocsPerRun(100, func() {
			nilSrc.InitCloneToBuf(&dst, make([]byte, 0))
		})
		require.Equal(t, 1.0, allocs)
	})

	t.Run("too-small buffer panics", func(t *testing.T) {
		var dst Bitmap
		require.Panics(t, func() {
			src.InitCloneToBuf(&dst, make([]byte, 0, 8))
		})
	})
}

package sroar

import (
	"testing"
)

// buildMaskedBitmap creates a bitmap with numKeys distinct keys, each holding
// valsPerKey values in its container. Keys are spread across positions so that
// applying mask collapses them into numUniqueAfterMask groups.
func buildMaskedBitmap(numKeys, valsPerKey, numUniqueAfterMask int) (*Bitmap, uint64) {
	bm := NewBitmap()

	// Use top 16 bits (48-63) to differentiate keys, mask will zero them
	// to cause collisions. Middle bits (16-47) cycle through numUniqueAfterMask
	// groups.
	//
	// mask keeps bits 16-47 and zeroes bits 48-63, causing keys with
	// the same middle bits to collapse.
	var mask uint64 = 0x0000FFFFFFFF0000

	for i := 0; i < numKeys; i++ {
		group := uint64(i % numUniqueAfterMask)
		pos := uint64(i / numUniqueAfterMask)
		key := (pos << 48) | (group << 16)
		for v := 0; v < valsPerKey; v++ {
			bm.Set(key | uint64(v))
		}
	}
	return bm, mask
}

// Benchmark scenarios:
//   - NoCollision: each key maps to a unique masked key (no merges)
//   - LowCollision: ~2 keys per masked group
//   - HighCollision: ~10 keys per masked group
//   - MassiveCollision: all keys collapse to 1 masked group
//
// Each scenario is tested with sparse (few values per container) and
// dense (many values per container) variants.

type maskedBenchCase struct {
	name               string
	numKeys            int
	valsPerKey         int
	numUniqueAfterMask int
}

var maskedBenchCases = []maskedBenchCase{
	// No collisions — pure copy path
	{"NoCollision_Sparse", 100, 10, 100},
	{"NoCollision_Dense", 100, 1000, 100},

	// Low collision — 2 keys per group
	{"LowCollision_Sparse", 100, 10, 50},
	{"LowCollision_Dense", 100, 1000, 50},

	// High collision — 10 keys per group
	{"HighCollision_Sparse", 100, 10, 10},
	{"HighCollision_Dense", 100, 1000, 10},

	// Massive collision — all keys collapse to 1
	{"MassiveCollision_Sparse", 100, 10, 1},
	{"MassiveCollision_Dense", 100, 1000, 1},

	// Large bitmap — 1000 keys, 10 per group
	{"Large_HighCollision_Sparse", 1000, 10, 100},
	{"Large_HighCollision_Dense", 1000, 1000, 100},
}

func BenchmarkMasked(b *testing.B) {
	for _, tc := range maskedBenchCases {
		bm, mask := buildMaskedBitmap(tc.numKeys, tc.valsPerKey, tc.numUniqueAfterMask)
		b.Run(tc.name, func(b *testing.B) {
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				bm.Masked(mask)
			}
		})
	}
}

func BenchmarkMaskedToBuf(b *testing.B) {
	for _, tc := range maskedBenchCases {
		bm, mask := buildMaskedBitmap(tc.numKeys, tc.valsPerKey, tc.numUniqueAfterMask)
		warm := bm.Masked(mask)
		buf := make([]byte, len(warm.data)*2+4096)

		b.Run(tc.name, func(b *testing.B) {
			b.ReportAllocs()
			for i := 0; i < b.N; i++ {
				bm.MaskedToBuf(mask, buf)
			}
		})
	}
}

package sroar

import (
	"math/rand"
	"sync"
	"testing"
)

// The fixtures are deterministic (fixed seeds), expensive to build (millions of
// inserts), and only ever probed — so they are constructed at most once per test
// binary and shared read-only across tests and benchmarks.
var (
	denseOnce   sync.Once
	denseShared *Bitmap
	mixedOnce   sync.Once
	mixedShared *Bitmap
)

// denseBitmap spreads 2M values over a 200M range: ~3050 array containers of
// ~650 values each. Exercises the array-container paths.
func denseBitmap() *Bitmap {
	denseOnce.Do(func() {
		b := NewBitmap()
		rng := rand.New(rand.NewSource(7))
		max := int64(200_000_000)
		for i := 0; i < 2_000_000; i++ {
			b.Set(uint64(rng.Int63n(max)))
		}
		denseShared = b
	})
	return denseShared
}

// mixedBitmap combines fully-populated bitmap containers, mid-density array
// containers, empty key ranges, and a sparse tail — so probes cross every
// container type and every miss shape.
func mixedBitmap() *Bitmap {
	mixedOnce.Do(func() {
		mixedShared = buildMixedBitmap()
	})
	return mixedShared
}

func buildMixedBitmap() *Bitmap {
	b := NewBitmap()
	// bitmap containers: every value in [0, 4<<16)
	for x := uint64(0); x < 4<<16; x++ {
		b.Set(x)
	}
	// gap: no containers for keys in [4<<16, 8<<16)
	// array containers: ~700/container over [8<<16, 12<<16)
	rng := rand.New(rand.NewSource(21))
	for i := 0; i < 2800; i++ {
		b.Set(uint64(8<<16) + uint64(rng.Int63n(4<<16)))
	}
	// dense-but-not-full bitmap containers: every even value in [16<<16, 18<<16)
	for x := uint64(16 << 16); x < 18<<16; x += 2 {
		b.Set(x)
	}
	// sparse tail: single-value containers far out
	for i := uint64(0); i < 20; i++ {
		b.Set(uint64(32<<16) + i*3*65536)
	}
	return b
}

// The cursor must match Bitmap.Contains for any access order, on both array and
// bitmap containers, hits and misses, present and absent keys.
func TestContainsCursorEquivalence(t *testing.T) {
	fixtures := []struct {
		name string
		bm   *Bitmap
		max  uint64
	}{
		{"dense_arrays", denseBitmap(), 200_000_000},
		{"mixed_containers", mixedBitmap(), 90 << 16},
	}
	for _, fx := range fixtures {
		t.Run(fx.name, func(t *testing.T) {
			rng := rand.New(rand.NewSource(99))
			cur := fx.bm.NewContainsCursor()
			for i := 0; i < 2_000_000; i++ { // random: forward gallops + backward fallbacks
				x := uint64(rng.Int63n(int64(fx.max)))
				if cur.Contains(x) != fx.bm.Contains(x) {
					t.Fatalf("random mismatch at %d", x)
				}
			}
			cur2 := fx.bm.NewContainsCursor()
			for x := uint64(0); x < fx.max; x += uint64(rng.Intn(97) + 1) { // monotonic
				if cur2.Contains(x) != fx.bm.Contains(x) {
					t.Fatalf("monotonic mismatch at %d", x)
				}
			}
		})
	}
}

func TestContainsCursorEdgeCases(t *testing.T) {
	t.Run("nil_cursor_and_nil_bitmap", func(t *testing.T) {
		var nilCur *ContainsCursor
		if nilCur.Contains(42) {
			t.Fatal("nil cursor must report false")
		}
		var nilBm *Bitmap
		if nilBm.NewContainsCursor().Contains(42) {
			t.Fatal("cursor over nil bitmap must report false")
		}
	})
	t.Run("zero_value_cursor", func(t *testing.T) {
		var cur ContainsCursor // embedded-by-value, never Reset
		if cur.Contains(0) || cur.Contains(42) {
			t.Fatal("zero-value cursor must report false")
		}
	})
	t.Run("empty_bitmap", func(t *testing.T) {
		cur := NewBitmap().NewContainsCursor()
		for _, x := range []uint64{0, 1, 65535, 65536, 1 << 40} {
			if cur.Contains(x) {
				t.Fatalf("empty bitmap: %d must be false", x)
			}
		}
	})
	t.Run("single_container", func(t *testing.T) {
		b := NewBitmap()
		b.Set(100)
		b.Set(200)
		cur := b.NewContainsCursor()
		checks := []struct {
			x    uint64
			want bool
		}{{0, false}, {100, true}, {150, false}, {200, true}, {65535, false}, {1 << 30, false}}
		for _, c := range checks {
			if got := cur.Contains(c.x); got != c.want {
				t.Fatalf("Contains(%d)=%v want %v", c.x, got, c.want)
			}
		}
	})
	t.Run("beyond_max_then_backward", func(t *testing.T) {
		b := denseBitmap()
		cur := b.NewContainsCursor()
		if cur.Contains(1 << 50) { // far past the last container
			t.Fatal("beyond-max must be false")
		}
		// backward probes after exhausting the key space must still be exact
		rng := rand.New(rand.NewSource(5))
		for i := 0; i < 100_000; i++ {
			x := uint64(rng.Int63n(200_000_000))
			if cur.Contains(x) != b.Contains(x) {
				t.Fatalf("backward-after-end mismatch at %d", x)
			}
		}
	})
	t.Run("reset_rebind", func(t *testing.T) {
		a, b := denseBitmap(), mixedBitmap()
		var cur ContainsCursor
		cur.Reset(a)
		rng := rand.New(rand.NewSource(11))
		for i := 0; i < 100_000; i++ {
			x := uint64(rng.Int63n(200_000_000))
			if cur.Contains(x) != a.Contains(x) {
				t.Fatalf("bound to a: mismatch at %d", x)
			}
		}
		cur.Reset(b) // rebind mid-life: no state may leak
		for i := 0; i < 100_000; i++ {
			x := uint64(rng.Int63n(90 << 16))
			if cur.Contains(x) != b.Contains(x) {
				t.Fatalf("rebound to b: mismatch at %d", x)
			}
		}
		cur.Reset(nil)
		if cur.Contains(1) {
			t.Fatal("rebound to nil: must report false")
		}
	})
}

// Contains vs ContainsCursor across three probe patterns: small forward gaps
// (probes mostly repeat a container), large forward gaps (every probe a new
// container, where the forward gallop beats the from-scratch search), and fully
// random (no locality — the cursor's worst case).
func BenchmarkContainsCursor(b *testing.B) {
	bm := denseBitmap()
	max := uint64(200_000_000)

	ascProbes := func(avgStep int) []uint64 {
		rng := rand.New(rand.NewSource(7))
		var probes []uint64
		for x := uint64(0); x < max; x += uint64(rng.Intn(avgStep) + 1) {
			probes = append(probes, x)
		}
		return probes
	}
	runAsc := func(b *testing.B, probes []uint64, useCursor bool) {
		b.ReportAllocs()
		// increment-and-wrap rather than i%n: a hardware integer division in the
		// timed loop would compress the measured Contains-vs-Cursor ratio.
		n := len(probes)
		var s int
		j := -1
		cur := bm.NewContainsCursor()
		for i := 0; i < b.N; i++ {
			j++
			if j == n {
				j = 0
				cur.Reset(bm) // wrapped: keep probes non-decreasing within a pass
			}
			hit := false
			if useCursor {
				hit = cur.Contains(probes[j])
			} else {
				hit = bm.Contains(probes[j])
			}
			if hit {
				s++
			}
		}
		sink = s
	}

	for _, rg := range []struct {
		name    string
		avgStep int
	}{{"smallgap", 50}, {"biggap", 400_000}} {
		probes := ascProbes(rg.avgStep)
		b.Run(rg.name+"/Contains", func(b *testing.B) { runAsc(b, probes, false) })
		b.Run(rg.name+"/Cursor", func(b *testing.B) { runAsc(b, probes, true) })
	}

	rng := rand.New(rand.NewSource(11))
	randp := make([]uint64, 1<<20)
	for i := range randp {
		randp[i] = uint64(rng.Int63n(int64(max)))
	}
	m := len(randp)
	b.Run("random/Contains", func(b *testing.B) {
		b.ReportAllocs()
		var s int
		for i := 0; i < b.N; i++ {
			if bm.Contains(randp[i%m]) {
				s++
			}
		}
		sink = s
	})
	b.Run("random/Cursor", func(b *testing.B) {
		b.ReportAllocs()
		cur := bm.NewContainsCursor()
		var s int
		for i := 0; i < b.N; i++ {
			if cur.Contains(randp[i%m]) {
				s++
			}
		}
		sink = s
	})
}

var sink int

// The reject-walk probe shapes: misses landing in the gap at the cursor and
// re-probes of the value the cursor sits on. Both are arrayHas early returns —
// one compare, no arrPos store — and regress first if that fast path is lost.
func BenchmarkContainsCursorGapShapes(b *testing.B) {
	bm := NewBitmap()
	for x := uint64(0); x < 8<<16; x += 17 { // ~3855/container: array containers
		bm.Set(x)
	}
	max := uint64(8 << 16)

	b.Run("gap_reject", func(b *testing.B) {
		cur := bm.NewContainsCursor()
		var s int
		y := uint64(1)
		for i := 0; i < b.N; i++ {
			if cur.Contains(y) { // 17k+1: always a miss in the gap ahead
				s++
			}
			y += 17
			if y >= max {
				y = 1
			}
		}
		sink = s
	})
	b.Run("at_cursor_hit", func(b *testing.B) {
		cur := bm.NewContainsCursor()
		var s int
		y := uint64(0)
		for i := 0; i < b.N; i += 2 {
			if cur.Contains(y) { // advance to y (hit)
				s++
			}
			if cur.Contains(y) { // re-probe the cursor position (hit)
				s++
			}
			y += 17
			if y >= max {
				y = 0
			}
		}
		sink = s
	})
}

package sroar

import (
	"math/rand"
	"sort"
	"sync"
	"testing"
)

var (
	denseValsOnce sync.Once
	denseVals     []uint64
	mixedValsOnce sync.Once
	mixedVals     []uint64
)

func denseValues() []uint64 {
	denseValsOnce.Do(func() { denseVals = denseBitmap().ToArray() })
	return denseVals
}

func mixedValues() []uint64 {
	mixedValsOnce.Do(func() { mixedVals = mixedBitmap().ToArray() })
	return mixedVals
}

func refNextGeq(vals []uint64, x uint64) (uint64, bool) {
	i := sort.Search(len(vals), func(i int) bool { return vals[i] >= x })
	if i < len(vals) {
		return vals[i], true
	}
	return 0, false
}

// NextGeq must return the exact successor for any probe, in any order, on both
// array and bitmap containers.
func TestNextGeqEquivalence(t *testing.T) {
	fixtures := []struct {
		name string
		bm   *Bitmap
		vals []uint64
		max  uint64
	}{
		{"dense_arrays", denseBitmap(), denseValues(), 200_000_000},
		{"mixed_containers", mixedBitmap(), mixedValues(), 90 << 16},
	}
	for _, fx := range fixtures {
		t.Run(fx.name, func(t *testing.T) {
			rng := rand.New(rand.NewSource(31))

			// leapfrog: ascending probes jumping from each successor
			cur := fx.bm.NewContainsCursor()
			x := uint64(0)
			for x < fx.max {
				got, gotOK := cur.NextGeq(x)
				want, wantOK := refNextGeq(fx.vals, x)
				if gotOK != wantOK || got != want {
					t.Fatalf("leapfrog NextGeq(%d) = (%d,%v), want (%d,%v)", x, got, gotOK, want, wantOK)
				}
				if !gotOK {
					break
				}
				if !cur.Contains(got) { // returned value must be set, cursor stays consistent
					t.Fatalf("Contains(NextGeq(%d)=%d) = false", x, got)
				}
				x = got + 1 + uint64(rng.Intn(100_000))
			}

			// random probes on a shared cursor (forward and backward jumps)
			cur2 := fx.bm.NewContainsCursor()
			for i := 0; i < 300_000; i++ {
				x := uint64(rng.Int63n(int64(fx.max)))
				got, gotOK := cur2.NextGeq(x)
				want, wantOK := refNextGeq(fx.vals, x)
				if gotOK != wantOK || got != want {
					t.Fatalf("random NextGeq(%d) = (%d,%v), want (%d,%v)", x, got, gotOK, want, wantOK)
				}
			}

			// interleaved Contains + NextGeq, ascending: both must stay exact
			cur3 := fx.bm.NewContainsCursor()
			x = 0
			for i := 0; i < 200_000 && x < fx.max; i++ {
				if i%3 == 0 {
					got, gotOK := cur3.NextGeq(x)
					want, wantOK := refNextGeq(fx.vals, x)
					if gotOK != wantOK || got != want {
						t.Fatalf("interleaved NextGeq(%d) = (%d,%v), want (%d,%v)", x, got, gotOK, want, wantOK)
					}
				} else {
					want, _ := refNextGeq(fx.vals, x)
					if got := cur3.Contains(x); got != (want == x) {
						t.Fatalf("interleaved Contains(%d) = %v, want %v", x, got, want == x)
					}
				}
				x += uint64(rng.Intn(200) + 1)
			}

			// exact boundaries
			first, last := fx.vals[0], fx.vals[len(fx.vals)-1]
			cur4 := fx.bm.NewContainsCursor()
			if v, ok := cur4.NextGeq(0); !ok || v != first {
				t.Fatalf("NextGeq(0) = (%d,%v), want (%d,true)", v, ok, first)
			}
			if v, ok := cur4.NextGeq(last); !ok || v != last {
				t.Fatalf("NextGeq(last) = (%d,%v), want (%d,true)", v, ok, last)
			}
			if _, ok := cur4.NextGeq(last + 1); ok {
				t.Fatal("NextGeq(last+1) must not find a successor")
			}
		})
	}
}

func TestNextGeqEdgeCases(t *testing.T) {
	t.Run("nil_and_empty", func(t *testing.T) {
		var nilCur *ContainsCursor
		if _, ok := nilCur.NextGeq(0); ok {
			t.Fatal("nil cursor")
		}
		if _, ok := NewBitmap().NewContainsCursor().NextGeq(0); ok {
			t.Fatal("empty bitmap")
		}
	})
	t.Run("skips_emptied_container", func(t *testing.T) {
		b := NewBitmap()
		b.Set(5)
		b.Remove(5) // key-0 container remains, empty
		b.Set(1<<16 + 3)
		cur := b.NewContainsCursor()
		if v, ok := cur.NextGeq(0); !ok || v != 1<<16+3 {
			t.Fatalf("NextGeq(0) = (%d,%v), want (%d,true)", v, ok, 1<<16+3)
		}
	})
	t.Run("crosses_container_gap", func(t *testing.T) {
		b := NewBitmap()
		b.Set(100)
		b.Set(7<<16 + 9) // keys 0 and 7, nothing between
		cur := b.NewContainsCursor()
		if v, ok := cur.NextGeq(101); !ok || v != 7<<16+9 {
			t.Fatalf("NextGeq(101) = (%d,%v)", v, ok)
		}
	})
	t.Run("within_bitmap_container", func(t *testing.T) {
		b := NewBitmap()
		for x := uint64(0); x < 65536; x += 7 {
			b.Set(x) // dense: bitmap container
		}
		vals := b.ToArray()
		cur := b.NewContainsCursor()
		rng := rand.New(rand.NewSource(3))
		for i := 0; i < 100_000; i++ {
			x := uint64(rng.Intn(65600))
			got, gotOK := cur.NextGeq(x)
			want, wantOK := refNextGeq(vals, x)
			if gotOK != wantOK || got != want {
				t.Fatalf("NextGeq(%d) = (%d,%v), want (%d,%v)", x, got, gotOK, want, wantOK)
			}
		}
	})
	// A same-key probe past the cached container's last value must fall through
	// to the "cached container exhausted" branch (idx = lastIdx+1) and let a
	// LATER container supply the successor. The random differential reaches the
	// array shape of this often but never the bitmap shape, so assert both.
	t.Run("bitmap_exhausted_then_later_container", func(t *testing.T) {
		b := NewBitmap()
		for x := uint64(0); x < 65536; x += 2 {
			b.Set(x) // 32768 values -> key-0 bitmap container; last set bit 65534
		}
		b.Set(2<<16 + 7)
		cur := b.NewContainsCursor()
		if v, ok := cur.NextGeq(100); !ok || v != 100 { // land in the key-0 bitmap
			t.Fatalf("NextGeq(100) = (%d,%v), want (100,true)", v, ok)
		}
		// same key 0, past the last set bit: bitmap.nextGeq fails, so the walk
		// must advance to the key-2 container's minimum.
		if v, ok := cur.NextGeq(65535); !ok || v != 2<<16+7 {
			t.Fatalf("NextGeq(65535) = (%d,%v), want (%d,true)", v, ok, 2<<16+7)
		}
	})
	t.Run("array_exhausted_then_later_container", func(t *testing.T) {
		b := NewBitmap()
		b.Set(10)
		b.Set(20) // key-0 array container
		b.Set(2<<16 + 7)
		cur := b.NewContainsCursor()
		if v, ok := cur.NextGeq(10); !ok || v != 10 { // land in the key-0 array
			t.Fatalf("NextGeq(10) = (%d,%v), want (10,true)", v, ok)
		}
		if v, ok := cur.NextGeq(21); !ok || v != 2<<16+7 { // past the array's max
			t.Fatalf("NextGeq(21) = (%d,%v), want (%d,true)", v, ok, 2<<16+7)
		}
	})
}

// Ascending small-gap jumps over denseBitmap (all array containers): jumps of
// ~1-2000 against ~650-value/container arrays keep almost every probe in the
// same container, so this measures the array same-container fast path
// (arrayGeqPos). It does NOT exercise bitmap.nextGeq or the cross-container
// walk — see BenchmarkNextGeqBitmap and BenchmarkNextGeqCrossContainer for those.
func BenchmarkNextGeqLeapfrog(b *testing.B) {
	bm := denseBitmap()
	max := uint64(200_000_000)
	rng := rand.New(rand.NewSource(9))
	// precompute jump offsets to keep RNG out of the timed loop
	gaps := make([]uint64, 1<<16)
	for i := range gaps {
		gaps[i] = uint64(rng.Intn(2000) + 1)
	}
	b.ReportAllocs()
	b.ResetTimer()
	cur := bm.NewContainsCursor()
	x := uint64(0)
	var s int
	for i := 0; i < b.N; i++ {
		v, ok := cur.NextGeq(x)
		if !ok {
			cur.Reset(bm)
			x = 0
			continue
		}
		s++
		x = v + gaps[i&(1<<16-1)]
		if x >= max {
			cur.Reset(bm)
			x = 0
		}
	}
	sink = s
}

var (
	bitmapContainersOnce   sync.Once
	bitmapContainersShared *Bitmap
)

// bitmapContainerFixture builds a bitmap whose every container is a bitmap
// container (cardinality > 4096), sparse enough (every 5th value) that
