package sroar

import (
	"fmt"
	"strings"
)

var (
	indexNodeSize  = 0
	indexNumKeys   = 1
	indexNodeStart = 2
)

// node stores uint64 keys and the corresponding container offset in the buffer.
// 0th index (indexNodeSize) is used for storing the size of node in bytes.
// 1st index (indexNumKeys) is used for storing the number of keys.
// 2nd index is where we start writing the key-value pairs.
type node []uint64

func keyOffset(i int) int { return indexNodeStart + 2*i }
func valOffset(i int) int { return indexNodeStart + 2*i + 1 }

func (n node) numKeys() int        { return int(n[indexNumKeys]) }
func (n node) size() int           { return int(n[indexNodeSize]) }
func (n node) maxKeys() int        { return (len(n) - indexNodeStart) / 2 }
func (n node) key(i int) uint64    { return n[keyOffset(i)] }
func (n node) val(i int) uint64    { return n[valOffset(i)] }
func (n node) data(i int) []uint64 { return n[keyOffset(i):keyOffset(i+1)] }

func (n node) uint64(idx int) uint64   { return n[idx] }
func (n node) setAt(idx int, k uint64) { n[idx] = k }

func (n node) setNumKeys(num int) { n[indexNumKeys] = uint64(num) }
func (n node) setNodeSize(sz int) { n[indexNodeSize] = uint64(sz) }

// addToAllVals adds delta to every container offset stored in the node.
// It is used when the key region grows and all offsets must be shifted right.
func (n node) addToAllVals(delta uint64) {
	for i := valOffset(0); i < valOffset(n.numKeys()); i += 2 {
		n[i] += delta
	}
}

func (n node) maxKey() uint64 {
	idx := n.numKeys()
	// numKeys == index of the max key, because 0th index is being used for meta information.
	if idx == 0 {
		return 0
	}
	return n.key(idx)
}

func (n node) moveRight(lo int) {
	hi := n.numKeys()
	assert(!n.isFull())
	// copy works despite of overlap in src and dst.
	// See https://golang.org/pkg/builtin/#copy
	copy(n[keyOffset(lo+1):keyOffset(hi+1)], n[keyOffset(lo):keyOffset(hi)])
}

// isFull checks that the node is already full.
func (n node) isFull() bool {
	return n.numKeys() == n.maxKeys()
}

// Search returns the index of a smallest key >= k in a node.
func (n node) search(k uint64) int {
	N := n.numKeys()
	if N == 0 {
		return 0
	}
	// n.key(0) is in the first cache line of the node and is always hot.
	// This check handles k before the first key or an exact match at position
	// 0 without entering the binary search.
	if k <= n.key(0) {
		return 0
	}
	lo, hi := 0, N-1
	for lo+8 <= hi {
		mid := lo + (hi-lo)/2
		ki := n.key(mid)
		// fmt.Printf("lo: %d mid: %d hi: %d. ki: %#x k: %#x\n", lo, mid, hi, ki, k)

		if ki < k {
			lo = mid + 1
		} else if ki > k {
			hi = mid
			// We should keep it equal, and not -1, because we'll take the first greater entry.
		} else {
			// fmt.Printf("returning mid: %d\n", mid)
			return mid
		}
	}
	for ; lo <= hi; lo++ {
		ki := n.key(lo)
		// fmt.Printf("itr. lo: %d hi: %d. ki: %#x k: %#x\n", lo, hi, ki, k)
		if ki >= k {
			return lo
		}
	}
	return N
	// if N < 4 {
	// simd.Search has a bug which causes this to return index 11 when it should be returning index
	// 9.
	// }
	// return int(simd.Search(n[keyOffset(0):keyOffset(N)], k))
}

// searchFrom returns the index of the smallest key >= k starting the search
// at position from. Uses exponential search to bracket the target then binary
// search to pinpoint it — O(log gap) where gap is the distance from from to
// the result. Equivalent to bi++ for gap=1, but much faster for large gaps.
func (n node) searchFrom(from int, k uint64) int {
	N := n.numKeys()
	lower := from + 1
	if lower >= N || n.key(lower) >= k {
		return lower
	}
	// Exponential expansion to bracket k.
	span := 1
	for lower+span < N && n.key(lower+span) < k {
		span *= 2
	}
	upper := lower + span
	if upper >= N {
		upper = N - 1
	}
	if n.key(upper) < k {
		return N
	}
	// Binary search within [lower + span/2, upper].
	lower += span >> 1
	for lower+1 < upper {
		mid := (lower + upper) >> 1
		ki := n.key(mid)
		if ki < k {
			lower = mid
		} else if ki > k {
			upper = mid
		} else {
			return mid
		}
	}
	return upper
}

// Search returns the index of a smallest key >= k in a node.
// Runs from highest to smallest key.
func (n node) searchReverse(k uint64) int {
	N := n.numKeys()
	idx := N

	for i := N - 1; i >= 0; i-- {
		if n.key(i) < k {
			break
		}
		idx = i
	}
	return idx
}

func zeroOut(data []uint64) {
	for i := 0; i < len(data); i++ {
		data[i] = 0
	}
}

// compacts the node i.e., remove all the kvs with value < lo. It returns the remaining number of
// keys.
func (n node) compact(lo uint64) int {
	N := n.numKeys()
	mk := n.maxKey()
	var left, right int
	for right = 0; right < N; right++ {
		if n.val(right) < lo && n.key(right) < mk {
			// Skip over this key. Don't copy it.
			continue
		}
		// Valid data. Copy it from right to left. Advance left.
		if left != right {
			copy(n.data(left), n.data(right))
		}
		left++
	}
	// zero out rest of the kv pairs.
	zeroOut(n[keyOffset(left):keyOffset(right)])
	n.setNumKeys(left)

	// If the only key we have is the max key, and its value is less than lo, then we can indicate
	// to the caller by returning a zero that it's OK to drop the node.
	if left == 1 && n.key(0) == mk && n.val(0) < lo {
		return 0
	}
	return left
}

// getValue returns the value corresponding to the key if found.
func (n node) getValue(k uint64) (uint64, bool) {
	k &= mask // Ensure k has its lowest bits unset.
	idx := n.search(k)
	// key is not found
	if idx >= n.numKeys() {
		return 0, false
	}
	if ki := n.key(idx); ki == k {
		return n.val(idx), true
	}
	return 0, false
}

// set returns true if it added a new key.
func (n node) set(k, v uint64) bool {
	var idx int
	N := n.numKeys()
	if N > 0 && k > n.key(N-1) {
		// Ascending inserts append past the last key; skip the binary search.
		idx = N
	} else {
		idx = n.search(k)
	}

	if idx < N {
		ki := n.key(idx)
		if N == n.maxKeys() {
			// This happens during split of non-root node, when we are updating the child pointer of
			// right node. Hence, the key should already exist.
			assert(ki == k)
		}
		if ki == k {
			n.setAt(valOffset(idx), v)
			return false
		}
		assert(ki > k)
		// Found the first entry which is greater than k. So, we need to fit k
		// just before it. For that, we should move the rest of the data in the
		// node to the right to make space for k.
		n.moveRight(idx)
	}
	n.setNumKeys(N + 1)
	n.setAt(keyOffset(idx), k)
	n.setAt(valOffset(idx), v)
	return true
}

func (n node) updateOffsets(beyond, by uint64, add bool) {
	for i := 0; i < n.numKeys(); i++ {
		if offset := n.val(i); offset > beyond {
			if add {
				n.setAt(valOffset(i), offset+by)
			} else {
				assert(offset >= by)
				n.setAt(valOffset(i), offset-by)
			}
		}
	}
}

func (n node) iterate(fn func(node, int)) {
	for i := 0; i < n.maxKeys(); i++ {
		if k := n.key(i); k > 0 {
			fn(n, i)
		} else {
			break
		}
	}
}

func (n node) print(parentID uint64) {
	var keys []string
	n.iterate(func(n node, i int) {
		keys = append(keys, fmt.Sprintf("%d", n.key(i)))
	})
	if len(keys) > 8 {
		copy(keys[4:], keys[len(keys)-4:])
		keys[3] = "..."
		keys = keys[:8]
	}
	fmt.Printf("num keys: %d keys: %s\n", n.numKeys(), strings.Join(keys, " "))
}

package sroar

import (
	"math/bits"
	"slices"
)

var emptyArrayContainer []uint16

func init() {
	emptyArrayContainer = make([]uint16, minContainerSize)
	emptyArrayContainer[indexType] = typeArray
	emptyArrayContainer[indexSize] = uint16(len(emptyArrayContainer))
	setCardinality(emptyArrayContainer, 0)
}

// andNotResultCard returns the cardinality of (ac &^ bc) without materializing
// or allocating, clamped at andNotCompactThreshold (above it the exact count is
// unused, as the source stays a maxContainerSize bitmap). A nil or empty bc
// leaves ac unchanged.
//
// Bitmap sources are counted from the cardinality header, not by recounting
// bits: bc removes at most bcCard values, so acCard-bcCard >= andNotCompactThreshold
// proves a dense result without any counting.
func andNotResultCard(ac, bc []uint16) int {
	acCard := getCardinality(ac)
	bcCard := 0
	if bc != nil {
		bcCard = getCardinality(bc)
	}
	if bcCard == 0 {
		// nothing to subtract: result is ac unchanged
		if ac[indexType] == typeBitmap {
			// clamp: a full bitmap's cardinality overflows the caller's uint16,
			// and the exact value above the threshold is unused
			return min(acCard, andNotCompactThreshold)
		}
		// an array result stays an array sized to this exact count, so no clamp
		return acCard
	}
	at, bt := ac[indexType], bc[indexType]
	switch {
	case at == typeArray && bt == typeArray:
		return acCard - intersection2by2Cardinality(array(ac).all(), array(bc).all())
	case at == typeArray && bt == typeBitmap:
		n := acCard
		for _, x := range array(ac).all() {
			if bitmap(bc).has(x) {
				n--
			}
		}
		return n
	case at == typeBitmap && bt == typeArray:
		if acCard-bcCard >= andNotCompactThreshold {
			return andNotCompactThreshold // dense by headers alone
		}
		// Start from acCard and drop each array element present in ac. n only
		// falls, so n-remaining is its floor; once that reaches the threshold
		// the result is dense no matter the rest.
		n := acCard
		remaining := bcCard
		for _, x := range array(bc).all() {
			remaining--
			if bitmap(ac).has(x) {
				n--
			}
			if n-remaining >= andNotCompactThreshold {
				return andNotCompactThreshold
			}
		}
		// the final iteration's floor check was n >= threshold, so here n < threshold
		return n
	case at == typeBitmap && bt == typeBitmap:
		if acCard-bcCard >= andNotCompactThreshold {
			return andNotCompactThreshold // dense by headers alone
		}
		a64 := uint16To64SliceUnsafe(ac[startIdx:])
		b64 := uint16To64SliceUnsafe(bc[startIdx:])
		n := 0
		for i := range a64 {
			n += bits.OnesCount64(a64[i] &^ b64[i])
			if n >= andNotCompactThreshold {
				return andNotCompactThreshold // dense: exact count not needed
			}
		}
		return n
	default:
		panic("andNotResultCard: We should not reach here")
	}
}

func containerAndAlt(ac, bc []uint16, optBuf []uint16, runMode int) []uint16 {
	at := ac[indexType]
	bt := bc[indexType]

	if at == typeArray && bt == typeArray {
		left := array(ac)
		right := array(bc)
		return left.andArrayAlt(right, optBuf, runMode)
	}
	if at == typeArray && bt == typeBitmap {
		left := array(ac)
		right := bitmap(bc)
		return left.andBitmapAlt(right, optBuf, runMode)
	}
	if at == typeBitmap && bt == typeArray {
		left := bitmap(ac)
		right := array(bc)
		return left.andArrayAlt(right, optBuf, runMode)
	}
	if at == typeBitmap && bt == typeBitmap {
		left := bitmap(ac)
		right := bitmap(bc)
		return left.andBitmapAlt(right, optBuf, runMode)
	}
	panic("containerAnd: We should not reach here")
}

func (c array) andArrayAlt(other array, optBuf []uint16, runMode int) []uint16 {
	cnum := getCardinality(c)
	onum := getCardinality(other)

	if cnum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// do nothing, array already empty
		return nil
	}
	if onum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// reset array
		c.zeroOut()
		return nil
	}

	// merge
	out := c
	if runMode&runInline == 0 {
		out = optBuf
		if out == nil {
			min := min(cnum, onum)
			out = make([]uint16, roundSize(startIdx+uint16(min)))
		}
	}
	setc := c.all()
	seto := other.all()
	num := intersection2by2(setc, seto, out[startIdx:])
	lastIdx := startIdx + uint16(num)

	if runMode&runInline == 0 {
		return bufAsArray(out, lastIdx)
	}
	setCardinality(c, num)
	return nil
}

func (c array) andBitmapAlt(other bitmap, optBuf []uint16, runMode int) []uint16 {
	cnum := getCardinality(c)
	onum := getCardinality(other)

	if cnum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// do nothing, array already empty
		return nil
	}
	if onum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// reset array
		c.zeroOut()
		return nil
	}

	// merge
	out := c
	if runMode&runInline == 0 {
		out = optBuf
		if out == nil {
			min := min(cnum, onum)
			out = make([]uint16, roundSize(startIdx+uint16(min)))
		}
	}
	lastIdx := startIdx
	for _, x := range c.all() {
		if other.has(x) {
			out[lastIdx] = x
			lastIdx++
		}
	}

	if runMode&runInline == 0 {
		return bufAsArray(out, lastIdx)
	}
	setCardinality(c, int(lastIdx-startIdx))
	return nil
}

func (b bitmap) andArrayAlt(other array, optBuf []uint16, runMode int) []uint16 {
	bnum := getCardinality(b)
	onum := getCardinality(other)

	if bnum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// do nothing, bitmap already empty
		return nil
	}
	if onum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// reset bitmap
		b.zeroOut()
		return nil
	}

	// merge
	if runMode&runInline == 0 {
		out := optBuf
		if out == nil {
			out = make([]uint16, roundSize(startIdx+uint16(onum)))
		}
		lastIdx := startIdx
		for _, x := range other.all() {
			if b.has(x) {
				out[lastIdx] = x
				lastIdx++
			}
		}

		return bufAsArray(out, lastIdx)
	}

	if optBuf == nil {
		// Two-pointer scan: process each uint64 word of b against sorted
		// elements of other — no scratch buffer or allocation needed.
		// For each word, the uint64 mask is built on the fly from other's elements.
		// Benchmarks show this is faster than the previous 1KB batch approach
		// and avoids any allocation.
		dst64 := uint16To64SliceUnsafe(b[startIdx:])
		src := other.all()
		j := 0
		num := 0
		for i := range dst64 {
			wordEnd := (i + 1) * 64 // int: avoids uint16 overflow at i=1023
			if j >= len(src) || int(src[j]) >= wordEnd {
				dst64[i] = 0
				continue
			}
			if dst64[i] == 0 {
				for j < len(src) && int(src[j]) < wordEnd {
					j++
				}
				continue
			}
			var mask uint64
			for j < len(src) && int(src[j]) < wordEnd {
				mask |= wordBit(src[j])
				j++
			}
			dst64[i] &= mask
			num += bits.OnesCount64(dst64[i])
		}
		setCardinality(b, num)
		return nil
	}

	data := optBuf[startIdx:]
	clear(data)
	for _, x := range other.all() {
		setBit(data, x)
	}

	dst64 := uint16To64SliceUnsafe(b[startIdx:])
	src64 := uint16To64SliceUnsafe(optBuf[startIdx:])
	var num int
	if bnum < maxCardinality/2 {
		// Sparse path: skip zero words — same threshold as andBitmapAlt.
		for i := range dst64 {
			if dst64[i] != 0 {
				dst64[i] &= src64[i]
				num += bits.OnesCount64(dst64[i])
			}
		}
	} else {
		for i := range dst64 {
			dst64[i] &= src64[i]
			num += bits.OnesCount64(dst64[i])
		}
	}
	setCardinality(b, num)
	return nil
}

func (b bitmap) andBitmapAlt(other bitmap, optBuf []uint16, runMode int) []uint16 {
	bnum := getCardinality(b)
	onum := getCardinality(other)

	if bnum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// do nothing, array already empty
		return nil
	}
	if onum == 0 {
		if runMode&runInline == 0 {
			return emptyArrayContainer
		}
		// reset bitmap
		b.zeroOut()
		return nil
	}

	// Non-inline: copy b into out first, then AND out with other in place.
	//
	// The seemingly redundant copy is intentional and faster than a direct
	// 3-way AND (dst = b & other). The copy pre-warms out in L1 cache so
	// the subsequent AND loop operates as a 2-stream read-modify-write
	// (out + other), which is more efficient than a 3-stream operation
	// (read b, read other, write out). Benchmarks confirmed the copy+AND
	// approach is ~25% faster than the 3-way AND on ARM64 (Apple M4 Pro).
	out := b
	if runMode&runInline == 0 {
		out = copyBitmap(b, optBuf)
	}

	dst64 := uint16To64SliceUnsafe(out[startIdx:])
	src64 := uint16To64SliceUnsafe(other[startIdx:])
	var num int
	if bnum < maxCardinality/2 {
		// Sparse path: skip zero words to avoid AND+POPCNT on empty words.
		// Faster below ~50% fill; above that the branch overhead exceeds the benefit.
		// Only bnum (density of dst) matters — dst64 words are from b/out.
		for i := range dst64 {
			if dst64[i] != 0 {
				dst64[i] &= src64[i]
				num += bits.OnesCount64(dst64[i])
			}
		}
	} else {
		for i := range dst64 {
			dst64[i] &= src64[i]
			num += bits.OnesCount64(dst64[i])
		}
	}
	setCardinality(out, num)

	if runMode&runInline == 0 {
		return out
	}
	return nil
}

func containerIntersects(ac, bc []uint16) bool {
	at := ac[indexType]
	bt := bc[indexType]
	if at == typeArray && bt == typeArray {
		return array(ac).intersectsArray(array(bc))
	}
	if at == typeArray && bt == typeBitmap {
		return array(ac).intersectsBitmap(bitmap(bc))
	}
	if at == typeBitmap && bt == typeArray {
		return array(bc).intersectsBitmap(bitmap(ac))
	}
	if at == typeBitmap && bt == typeBitmap {
		return bitmap(ac).intersectsBitmap(bitmap(bc))
	}
	panic("containerIntersects: We should not reach here")
}

func (c array) intersectsArray(other array) bool {
	cs := c.all()
	os := other.all()
	ci, oi := 0, 0
	for ci < len(cs) && oi < len(os) {
		if cs[ci] == os[oi] {
			return true
		} else if cs[ci] < os[oi] {
			ci++
		} else {
			oi++
		}
	}
	return false
}

func (c array) intersectsBitmap(other bitmap) bool {
	return slices.ContainsFunc(c.all(), other.has)
}

func (b bitmap) intersectsBitmap(other bitmap) bool {
	bs := uint16To64SliceUnsafe(b[startIdx:])
	os := uint16To64SliceUnsafe(other[startIdx:])
	for i := range bs {
		if bs[i]&os[i] != 0 {
			return true
		}
	}
	return false
}

// containerAndNotAlt computes ac &^ bc. A nil bc means nothing to subtract.
//
// Inline (runMode&runInline): subtracts bc from ac in place.
//
// Non-inline: writes the result into dst, whose length selects the output form —
// a full bitmap when len(dst) == maxContainerSize, otherwise a compact array.
// The result is produced straight into dst with no workspace: an array source
// subtracts into the slot; a dense bitmap is copied in and subtracted in place;
// a sparse bitmap has its survivors enumerated into the slot. A compact array's
// spare tail is left uninitialized — array reads never look past the cardinality.
func containerAndNotAlt(ac, bc, dst []uint16, runMode int) []uint16 {
	if runMode&runInline == 0 {
		out := dst[startIdx:]
		var w int
		switch ac[indexType] {
		case typeArray:
			a := array(ac)
			switch {
			case bc == nil:
				w = copy(out, a.all())
			case bc[indexType] == typeArray:
				w = a.andNotArrayIntoArray(array(bc), out)
			case bc[indexType] == typeBitmap:
				w = a.andNotBitmapIntoArray(bitmap(bc), out)
			default:
				panic("containerAndNot: unknown bc container type")
			}
		case typeBitmap:
			if len(dst) == maxContainerSize {
				// dense result stays a bitmap: subtract in place inside the slot
				copy(dst, ac)
				containerAndNotAlt(dst, bc, nil, runInline)
				return dst
			}
			// sparse result: enumerate the survivors into the slot as an array
			b := bitmap(ac)
			switch {
			case bc == nil:
				w = b.intoArray(out)
			case bc[indexType] == typeArray:
				w = b.andNotArrayIntoArray(array(bc), out)
			case bc[indexType] == typeBitmap:
				w = b.andNotBitmapIntoArray(bitmap(bc), out)
			default:
				panic("containerAndNot: unknown bc container type")
			}
		default:
			panic("containerAndNot: unknown ac container type")
		}
		setArrayHeader(dst, w)
		return dst
	}

	if bc == nil {
		return nil // subtracting nothing leaves ac unchanged
	}
	at := ac[indexType]
	bt := bc[indexType]
	switch {
	case at == typeArray && bt == typeArray:
		array(ac).andNotArrayAlt(array(bc))
	case at == typeArray && bt == typeBitmap:
		array(ac).andNotBitmapAlt(bitmap(bc))
	case at == typeBitmap && bt == typeArray:
		bitmap(ac).andNotArrayAlt(array(bc))
	case at == typeBitmap && bt == typeBitmap:
		bitmap(ac).andNotBitmapAlt(bitmap(bc))
	default:
		panic("containerAndNot: We should not reach here")
	}
	return nil
}

// The four andNot*Alt methods subtract other from the receiver in place. An
// empty receiver or an empty other leaves the receiver untouched.

func (c array) andNotArrayAlt(other array) {
	if getCardinality(c) == 0 || getCardinality(other) == 0 {
		return
	}
	setCardinality(c, c.andNotArrayIntoArray(other, c[startIdx:]))
}

func (c array) andNotBitmapAlt(other bitmap) {
	if getCardinality(c) == 0 || getCardinality(other) == 0 {
		return
	}
	setCardinality(c, c.andNotBitmapIntoArray(other, c[startIdx:]))
}

// andNotArrayIntoArray writes the ascending values of (c &^ other) into out,
// returning the count. Array minus array is exactly a set difference.
func (c array) andNotArrayIntoArray(other array, out []uint16) int {
	return difference(c.all(), other.all(), out)
}

// andNotBitmapIntoArray writes the ascending values of (c &^ other) into out
// and returns the count, keeping the values not present in other.
func (c array) andNotBitmapIntoArray(other bitmap, out []uint16) int {
	w := 0
	for _, x := range c.all() {
		if !other.has(x) {
			out[w] = x
			w++
		}
	}
	return w
}

func (b bitmap) andNotArrayAlt(other array) {
	bnum := getCardinality(b)
	if bnum == 0 || getCardinality(other) == 0 {
		return
	}
	delnum := 0
	data := b[startIdx:]
	for _, x := range other.all() {
		if hasBit(data, x) {
			clearBit(data, x)
			delnum++
		}
	}
	setCardinality(b, bnum-delnum)
}

func (b bitmap) andNotBitmapAlt(other bitmap) {
	if getCardinality(b) == 0 || getCardinality(other) == 0 {
		return
	}
	dst64 := uint16To64SliceUnsafe(b[startIdx:])
	src64 := uint16To64SliceUnsafe(other[startIdx:])
	var num int
	for i := range dst64 {
		dst64[i] &^= src64[i]
		num += bits.OnesCount64(dst64[i])
	}
	setCardinality(b, num)
}

// containerOrAlt returns the union of ac and bc. Under runInline it merges into
// ac and returns nil when ac's slot fits the result. Otherwise it returns a
// container that starts at buf, or one of the inputs, which is ac only without runInline.
func containerOrAlt(ac, bc []uint16, buf []uint16, runMode int) []uint16 {
	at := ac[indexType]
	bt := bc[indexType]

	if at == typeArray && bt == typeArray {
		left := array(ac)
		right := array(bc)
		return left.orArrayAlt(right, buf, runMode)
	}
	if at == typeArray && bt == typeBitmap {
		left := array(ac)
		right := bitmap(bc)
		return left.orBitmapAlt(right, buf, runMode)
	}
	if at == typeBitmap && bt == typeArray {
		left := bitmap(ac)
		right := array(bc)
		return left.orArrayAlt(right, buf, runMode)
	}
	if at == typeBitmap && bt == typeBitmap {
		left := bitmap(ac)
		right := bitmap(bc)
		return left.orBitmapAlt(right, buf, runMode)
	}
	panic("containerOr: We should not reach here")
}

func (c array) orArrayAlt(other array, buf []uint16, runMode int) []uint16 {
	cnum := getCardinality(c)
	onum := getCardinality(other)

	inline := runMode&runInline != 0
	size := c[indexSize]

	// An empty side never changes the other's type.
	if onum == 0 {
		if inline {
			return nil
		}
		return resizeArray(c, buf)
	}
	if cnum == 0 {
		if !inline || onum > int(size-startIdx) {
			return resizeArray(other, buf)
		}
		copy(c[startIdx:], other.all())
		setCardinality(c, onum)
		return nil
	}

	// A bitmap-sized slot keeps the union as a bitmap, so later Ors set bits in place.
	if inline && size == maxContainerSize {
		return c.orArrayAsBitmap(other, buf, runMode)
	}
	if inline && int(startIdx)+cnum+onum <= int(size) {
		c.orArrayInPlace(other)
		return nil
	}
	// Arrays past 2044 values, from OrOld or older data, may sum past buf's room for union2by2.
	if !isArrayCard(max(cnum, onum)) {
		return c.orArrayAsBitmap(other, buf, runMode)
	}
	if !isArrayCard(cnum+onum) && !c.unionMayFitArray(other, runMode) {
		return c.orArrayAsBitmap(other, buf, runMode)
	}
	num := union2by2(c.all(), other.all(), buf[startIdx:])
	if inline && c.canFitArray(num) {
		copy(c[startIdx:], buf[startIdx:int(startIdx)+num])
		setCardinality(c, num)
		return nil
	}
	if !isArrayCard(num) {
		// The merged values occupy buf, so the bitmap is built from c and other.
		return c.orArrayAsBitmap(other, buf, runMode)
	}
	return bufAsArray(buf, startIdx+uint16(num))
}

// unionMayFitArray reports false when a lower bound on the union of the
// non-empty c and other rules out storing it as an array. The bound counts each
// array's values outside the other's range, and is exact when either is a run.
func (c array) unionMayFitArray(other array, runMode int) bool {
	fitsArray := func(n int) bool {
		return isArrayCard(n) || runMode&runInline != 0 && c.canFitArray(n)
	}
	a, b := c.all(), other.all()
	lastA, lastB := a[len(a)-1], b[len(b)-1]
	if lastA < b[0] || lastB < a[0] {
		return fitsArray(len(a) + len(b))
	}
	var newA, newB int
	if a[0] < b[0] {
		newA, _ = slices.BinarySearch(a, b[0])
	} else if b[0] < a[0] {
		newB, _ = slices.BinarySearch(b, a[0])
	}
	if !fitsArray(max(len(a)+newB, len(b)+newA)) {
		return false
	}
	if lastA > lastB {
		k, _ := slices.BinarySearch(a, lastB+1)
		newA += len(a) - k
	} else if lastB > lastA {
		k, _ := slices.BinarySearch(b, lastA+1)
		newB += len(b) - k
	}
	return fitsArray(max(len(a)+newB, len(b)+newA))
}

// isArrayCard reports whether n values make an array container.
func isArrayCard(n int) bool {
	_, typ := containerSizeForCard(n)
	return typ == typeArray
}

// canFitArray reports whether an in-place Or leaves an array of n values in c's
// slot. A bitmap-sized slot always takes the bitmap.
func (c array) canFitArray(n int) bool {
	size := c[indexSize]
	return size != maxContainerSize && n <= int(size-startIdx)
}

// orArrayAsBitmap builds the union of c and other as a bitmap in buf. The
// union must not be array-sized unless c's slot keeps it.
func (c array) orArrayAsBitmap(other array, buf []uint16, runMode int) []uint16 {
	out := buf[:maxContainerSize]
	clear(out[startIdx:])
	out[indexType] = typeBitmap
	out[indexSize] = maxContainerSize

	data := out[startIdx:]
	num := orValues(data, c.all()) + orValues(data, other.all())
	setCardinality(out, num)
	return c.bitmapUnionResult(out, runMode)
}

// bitmapUnionResult puts out, the union of c and another container built as a
// bitmap, into c's slot under runInline when it fits, and otherwise returns it.
// A bitmap-sized slot keeps the bitmap, since compaction picks the type anyway.
func (c array) bitmapUnionResult(out []uint16, runMode int) []uint16 {
	if runMode&runInline == 0 {
		return out
	}
	if c[indexSize] == maxContainerSize {
		copy(c, out)
		return nil
	}
	num := getCardinality(out)
	if !c.canFitArray(num) {
		return out
	}
	bitmap(out).intoArray(c[startIdx : int(startIdx)+num])
	setCardinality(c, num)
	return nil
}

// orArrayInPlace merges other into c without a buffer. c's slot must have room
// for cnum+onum values, since duplicates are dropped only at the end.
func (c array) orArrayInPlace(other array) {
	if &c[0] == &other[0] {
		return
	}
	cnum := getCardinality(c)
	end := cnum + getCardinality(other)
	data := c[startIdx:]
	n1, pos := union2by2Backward(data, cnum, end, other.all())
	dups := pos - n1
	if dups > 0 {
		copy(data[n1:], data[pos:end])
	}
	setCardinality(c, end-dups)
}

// union2by2Backward merges the ascending set2 into the sorted set1[:n1],
// writing downwards from set1[pos-1], and returns the new n1 and pos. pos-n1
// must be at least len(set2), or a write lands on an unread value. When pos-n1
// starts at len(set2), the returned pos-n1 is the duplicate count.
func union2by2Backward(set1 []uint16, n1, pos int, set2 []uint16) (int, int) {
	i := n1 - 1 // set1's last unread value
	// Values above the other set's maximum move as one block.
	if j := len(set2) - 1; j >= 0 && i >= 0 {
		if top := set2[j]; set1[i] > top {
			k, found := slices.BinarySearch(set1[:i+1], top)
			if found {
				k++
			}
			pos -= i + 1 - k
			copy(set1[pos:], set1[k:i+1])
			i = k - 1
		} else if set1[i] < top {
			k, _ := slices.BinarySearch(set2, set1[i]+1)
			pos -= j + 1 - k
			copy(set1[pos:], set2[k:])
			set2 = set2[:k]
		}
	}
	for j := len(set2) - 1; j >= 0; j-- {
		if i < 0 {
			pos -= j + 1
			copy(set1[pos:], set2[:j+1])
			return 0, pos
		}
		v := set2[j]
		for i >= 0 && set1[i] > v {
			pos--
			set1[pos] = set1[i]
			i--
		}
		if i >= 0 && set1[i] == v {
			i--
		}
		pos--
		set1[pos] = v
	}
	return i + 1, pos
}

func (c array) orBitmapAlt(other bitmap, buf []uint16, runMode int) []uint16 {
	cnum := getCardinality(c)
	onum := getCardinality(other)
	inline := runMode&runInline != 0

	if onum == 0 {
		if inline {
			return nil
		}
		return resizeArray(c, buf)
	}
	// An empty c takes other's values as an array when its slot holds them.
	if cnum == 0 && inline && c.canFitArray(onum) {
		other.intoArray(c[startIdx : int(startIdx)+onum])
		setCardinality(c, onum)
		return nil
	}
	if cnum == 0 || onum == maxCardinality {
		if !inline || c[indexSize] != maxContainerSize {
			return other
		}
		copy(c, other)
		return nil
	}

	// Copying other and setting c's bits skips the popcount over all 1024 uint64
	// words that converting c and ORing two bitmaps would need.
	// A union that does not stay in c is returned as this bitmap even when array-sized.
	out := buf[:maxContainerSize]
	copy(out, other)
	setCardinality(out, onum+orValues(out[startIdx:], c.all()))
	return c.bitmapUnionResult(out, runMode)
}

func (b bitmap) orArrayAlt(other array, buf []uint16, runMode int) []uint16 {
	bnum := getCardinality(b)
	onum := getCardinality(other)

	if onum == 0 || bnum == maxCardinality {
		if runMode&runInline == 0 {
			return b
		}
		// do nothing, nothing to add
		return nil
	}
	if bnum == 0 {
		if runMode&runInline == 0 {
			return resizeArray(other, buf)
		}
		// proceed to merge
	}

	// merge
	out := b
	if runMode&runInline == 0 {
		out = buf
		copy(out, b)
	}

	// Counting new bits as they are set is faster than OR-all + POPCNT sweep
	// at array cardinalities.
	addnum := orValues(out[startIdx:], other.all())
	setCardinality(out, bnum+addnum)

	if runMode&runInline == 0 {
		return out
	}
	return nil
}

func (b bitmap) orBitmapAlt(other bitmap, buf []uint16, runMode int) []uint16 {
	bnum := getCardinality(b)
	onum := getCardinality(other)

	if onum == 0 || bnum == maxCardinality {
		if runMode&runInline == 0 {
			return b
		}
		// do nothing, nothing to add
		return nil
	}
	if bnum == 0 || onum == maxCardinality {
		if runMode&runInline == 0 {
			return other
		}
		// overwrite bitmap
		copy(b, other)
		return nil
	}

	// Non-inline: copy b into out first, then OR other into out in place.
	// The copy is intentional — it pre-warms out in L1 cache so the OR loop
	// operates as a 2-stream read-modify-write (out + other), which is faster
	// than a 3-stream operation (read b, read other, write out).
	out := b
	if runMode&runInline == 0 {
		out = buf
		copy(out, b)
	}

	dst64 := uint16To64SliceUnsafe(out[startIdx:])
	src64 := uint16To64SliceUnsafe(other[startIdx:])
	var num int
	for i := range dst64 {
		dst64[i] |= src64[i]
		num += bits.OnesCount64(dst64[i])
	}
	setCardinality(out, num)

	if runMode&runInline == 0 {
		return out
	}
	return nil
}

func resizeArray(c array, out []uint16) []uint16 {
	csize := c[indexSize]
	cnum := getCardinality(c)
	lastIdx := startIdx + uint16(cnum)
	size := roundSize(lastIdx)

	if size == csize {
		return c
	}

	if out == nil {
		out = make([]uint16, size)
	} else {
		out = out[:size]
	}
	setArrayHeader(out, cnum)
	copy(out[startIdx:], c[startIdx:lastIdx])
	return out
}

func copyBitmap(b bitmap, out []uint16) []uint16 {
	if out == nil {
		out = make([]uint16, maxContainerSize)
	}
	copy(out, b)
	return out
}

func bufAsArray(buf []uint16, lastIdx uint16) []uint16 {
	out := buf[:roundSize(lastIdx)]
	setArrayHeader(out, int(lastIdx-startIdx))
	return out
}

func roundSize(size uint16) uint16 {
	// <=64 -> 64
	// <=128 -> 128
	// <=256 -> 256
	// <=512 -> 512
	// <=1024 -> 1024
	// <=2048 -> 2048
	//  >2048 -> maxSize
	for i := uint16(64); i <= 2048; i *= 2 {
		if size <= i {
			return i
		}
	}
	return maxContainerSize
}

